mapper.select:
select
    (select count(1)
     from vol_volunteer_profile p


             and p.organization like concat('%', #{organization}, '%')


             and p.real_name like concat('%', #{volunteerRealName}, '%')

         and date(p.create_time) >= #{beginDate}
         and date(p.create_time) <= #{endDate}
     ) as volunteer_total,
    (select count(1)
     from vol_volunteer_profile p

         and p.audit_status = 1

             and p.organization like concat('%', #{organization}, '%')


             and p.real_name like concat('%', #{volunteerRealName}, '%')

         and date(p.create_time) >= #{beginDate}
         and date(p.create_time) <= #{endDate}
     ) as approved_volunteer_total,
    (select count(1)
     from vol_activity a

         and a.id = #{activityId}

             and a.title like concat('%', #{activityTitle}, '%')

         and date(a.start_time) >= #{beginDate}
         and date(a.start_time) <= #{endDate}
     ) as activity_total,
    (select count(1)
     from vol_activity a

         and a.status = 1
         and a.id = #{activityId}

             and a.title like concat('%', #{activityTitle}, '%')

         and date(a.start_time) >= #{beginDate}
         and date(a.start_time) <= #{endDate}
     ) as published_activity_total,
    (select count(1)
     from vol_activity_signup s
     left join vol_activity a on a.id = s.activity_id
     left join vol_volunteer_profile p on p.user_id = s.volunteer_user_id

         and s.activity_id = #{activityId}

             and a.title like concat('%', #{activityTitle}, '%')


             and p.organization like concat('%', #{organization}, '%')


             and p.real_name like concat('%', #{volunteerRealName}, '%')

         and date(s.create_time) >= #{beginDate}
         and date(s.create_time) <= #{endDate}
     ) as signup_total,
    (select count(1)
     from vol_activity_signup s
     left join vol_activity a on a.id = s.activity_id
     left join vol_volunteer_profile p on p.user_id = s.volunteer_user_id

         and s.status = 1
         and s.activity_id = #{activityId}

             and a.title like concat('%', #{activityTitle}, '%')


             and p.organization like concat('%', #{organization}, '%')


             and p.real_name like concat('%', #{volunteerRealName}, '%')

         and date(s.create_time) >= #{beginDate}
         and date(s.create_time) <= #{endDate}
     ) as approved_signup_total,
    (select count(1)
     from vol_checkin_record c
     left join vol_activity a on a.id = c.activity_id
     left join vol_volunteer_profile p on p.user_id = c.volunteer_user_id

         and c.checkin_time is not null
         and c.activity_id = #{activityId}

             and a.title like concat('%', #{activityTitle}, '%')


             and p.organization like concat('%', #{organization}, '%')


             and p.real_name like concat('%', #{volunteerRealName}, '%')

         and date(c.checkin_time) >= #{beginDate}
         and date(c.checkin_time) <= #{endDate}
     ) as checkin_total,
    (select count(1)
     from vol_checkin_record c
     left join vol_activity a on a.id = c.activity_id
     left join vol_volunteer_profile p on p.user_id = c.volunteer_user_id

         and c.status = 1
         and c.activity_id = #{activityId}

             and a.title like concat('%', #{activityTitle}, '%')


             and p.organization like concat('%', #{organization}, '%')


             and p.real_name like concat('%', #{volunteerRealName}, '%')

         and date(c.checkin_time) >= #{beginDate}
         and date(c.checkin_time) <= #{endDate}
     ) as checkout_total,
    (select count(1)
     from vol_service_record r
     left join vol_activity a on a.id = r.activity_id
     left join vol_volunteer_profile p on p.user_id = r.volunteer_user_id

         and r.status = 1
         and r.activity_id = #{activityId}

             and a.title like concat('%', #{activityTitle}, '%')


             and p.organization like concat('%', #{organization}, '%')


             and p.real_name like concat('%', #{volunteerRealName}, '%')

         and r.service_date >= #{beginDate}
         and r.service_date <= #{endDate}
     ) as service_record_total,
    (select ifnull(sum(r.service_minutes), 0)
     from vol_service_record r
     left join vol_activity a on a.id = r.activity_id
     left join vol_volunteer_profile p on p.user_id = r.volunteer_user_id

         and r.status = 1
         and r.activity_id = #{activityId}

             and a.title like concat('%', #{activityTitle}, '%')


             and p.organization like concat('%', #{organization}, '%')


             and p.real_name like concat('%', #{volunteerRealName}, '%')

         and r.service_date >= #{beginDate}
         and r.service_date <= #{endDate}
     ) as service_minutes_total,
    ((select count(1)
      from vol_service_record r
      left join vol_activity a on a.id = r.activity_id
      left join vol_volunteer_profile p on p.user_id = r.volunteer_user_id

          and r.status = 2
          and r.activity_id = #{activityId}

              and a.title like concat('%', #{activityTitle}, '%')


              and p.organization like concat('%', #{organization}, '%')


              and p.real_name like concat('%', #{volunteerRealName}, '%')

          and r.service_date >= #{beginDate}
          and r.service_date <= #{endDate}
      )
     +
     (select count(1)
      from vol_checkin_record c
      left join vol_activity a on a.id = c.activity_id
      left join vol_volunteer_profile p on p.user_id = c.volunteer_user_id

          and c.status = 2
          and c.activity_id = #{activityId}

              and a.title like concat('%', #{activityTitle}, '%')


              and p.organization like concat('%', #{organization}, '%')


              and p.real_name like concat('%', #{volunteerRealName}, '%')

          and date(c.checkin_time) >= #{beginDate}
          and date(c.checkin_time) <= #{endDate}
      )) as abnormal_total
